<script setup lang="ts">
import {getRequestError} from '~/utils/errors'
definePageMeta({layout:false})
useSeoMeta({title:'Administrator sign in · BARNALI',robots:'noindex,nofollow'})
const route=useRoute();const auth=useAuth();const email=ref('');const password=ref('');const showPassword=ref(false);const busy=ref(false);const error=ref('')
async function submit(){busy.value=true;error.value='';try{const user=await auth.login(email.value.trim(),password.value);if(user?.mustChangePassword)return navigateTo('/account/password');if(user?.role==='MEMBER')return navigateTo('/admin/access-denied');const next=typeof route.query.next==='string'&&route.query.next.startsWith('/')&&!route.query.next.startsWith('//')?route.query.next:'/admin';return navigateTo(next)}catch(cause:unknown){error.value=getRequestError(cause,'We could not sign you in. Check your credentials or try recovery.')}finally{busy.value=false}}
</script>
<template><main class="auth-page"><section class="auth-story"><BarnaliBrand tagline/><div class="auth-story__content"><div class="auth-story__tag">BARNALI · SECURE ADMINISTRATION</div><h1>Care for the community, <em>with care.</em></h1><p>Administrative access is limited to authorized team members.</p></div></section><section class="auth-panel-wrap"><div class="auth-panel"><div class="auth-panel__head"><BarnaliBrand compact/><div><h2>Administrator sign in</h2><p>Use your BARNALI account credentials.</p></div></div><p v-if="route.query.passwordChange==='required'" class="notice" role="status">Set a new password before continuing.</p><p v-if="error" class="notice notice--error" role="alert">{{error}}</p><form class="auth-form" @submit.prevent="submit"><div class="form-field"><label for="admin-email">Email address</label><input id="admin-email" v-model="email" class="input" type="email" autocomplete="username" required maxlength="254"></div><div class="form-field"><label for="admin-password">Password</label><div class="password-wrap"><input id="admin-password" v-model="password" class="input input--with-action" :type="showPassword?'text':'password'" autocomplete="current-password" required maxlength="72"><button class="password-toggle" type="button" :aria-label="showPassword?'Hide password':'Show password'" @click="showPassword=!showPassword"><IconGlyph :name="showPassword?'eye-off':'eye'"/></button></div></div><div class="auth-form__row"><NuxtLink to="/forgot-password">Forgot password?</NuxtLink><NuxtLink to="/login">Community sign in</NuxtLink></div><button class="btn" :disabled="busy">{{busy?'Signing in…':'Sign in to admin →'}}</button></form><p class="muted">Successful authentication alone does not grant admin access. Permissions are checked by the server.</p></div></section></main></template>
